from collections import deque


def rebuild_tree(preorder, inorder):
    if len(preorder) != len(inorder):
        return []
    if len(set(preorder)) != len(preorder) or set(preorder) != set(inorder):
        return []
    idx = {v: i for i, v in enumerate(inorder)}
    pos = [0]
    valid = [True]

    def build(lo, hi):
        if lo > hi:
            return None
        root_val = preorder[pos[0]]
        pos[0] += 1
        k = idx[root_val]
        if not (lo <= k <= hi):
            valid[0] = False
            return None
        node = {'val': root_val, 'left': None, 'right': None}
        node['left'] = build(lo, k - 1)
        node['right'] = build(k + 1, hi)
        return node

    root = build(0, len(inorder) - 1)
    if not valid[0] or root is None:
        return []
    out = []
    q = deque([root])
    while q:
        node = q.popleft()
        if node is None:
            out.append(None)
            continue
        out.append(node['val'])
        q.append(node['left'])
        q.append(node['right'])
    while out and out[-1] is None:
        out.pop()
    return out
